    document.title = title;
    const setMeta = (sel, val) => { const el = document.querySelector(sel); if (el) el.setAttribute('content', val); };
    setMeta('meta[name="description"]', desc);
    setMeta('meta[name="keywords"]', 'external display video player, iPhone video player external screen, play video on TV iPhone, MKV player iPhone external display, video player iPhone monitor, free video player iPhone TV, reposition video external screen, resize video external monitor, no black bars video player iPhone, iPhone video player HDMI, AVI player iPhone external display, WMV player iPhone, MP4 player external monitor iPhone, Bluetooth keyboard video control iPhone, iPhone video remote control TV');
    setMeta('meta[property="og:title"]', title);
    setMeta('meta[property="og:description"]', desc);
    setCanonical(window.location.pathname);
