import { useEffect, useRef, useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { X } from 'lucide-react';

/**
 * Renders an imported article fragment and gives its figures a click-to-zoom
 * lightbox. The HTML comes from our own content pack at build time, so it is
 * trusted markup, not user input.
 */
export default function ArticleBody({ html }) {
  const { t } = useTranslation('edb');
  const ref = useRef(null);
  const [zoomed, setZoomed] = useState(null);

  const close = useCallback(() => setZoomed(null), []);

  // Portrait figures (a sidebar crop, a settings pane) get .is-tall so the
  // stylesheet caps them by height. Without it a 432×1304 screenshot is
  // stretched to the column width and renders two thousand pixels tall.
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const mark = (img) => {
      const w = img.naturalWidth || Number(img.getAttribute('width')) || 0;
      const h = img.naturalHeight || Number(img.getAttribute('height')) || 0;
      if (w && h) img.closest('figure')?.classList.toggle('is-tall', h / w > 1.1);
    };
    for (const img of el.querySelectorAll('figure img')) {
      mark(img);
      if (!img.complete) img.addEventListener('load', () => mark(img), { once: true });
    }
  }, [html]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onClick = (e) => {
      const img = e.target.closest('figure img');
      if (!img) return;
      e.preventDefault();
      setZoomed({ src: img.currentSrc || img.src, alt: img.alt, caption: img.closest('figure')?.querySelector('figcaption')?.textContent || '' });
    };
    el.addEventListener('click', onClick);
    return () => el.removeEventListener('click', onClick);
  }, [html]);

  useEffect(() => {
    if (!zoomed) return;
    const onKey = (e) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', onKey);
    document.documentElement.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.documentElement.style.overflow = '';
    };
  }, [zoomed, close]);

  return (
    <>
      <div ref={ref} className="xeos-article" dangerouslySetInnerHTML={{ __html: html }} />
      {zoomed && (
        <div className="xeos-lightbox" onClick={close} role="dialog" aria-modal="true" aria-label={zoomed.alt || t('imageLightbox.altFallback')}>
          <button className="xeos-lightbox-close" onClick={close} aria-label={t('imageLightbox.close')}><X size={22} /></button>
          <figure onClick={(e) => e.stopPropagation()}>
            <img src={zoomed.src} alt={zoomed.alt} />
            {zoomed.caption && <figcaption>{zoomed.caption}</figcaption>}
          </figure>
        </div>
      )}
    </>
  );
}
